function updateOwnershipPath(){
  $('#chainRecordName').textContent=$('#recordOwnerInput').value.trim()||'—';
  $('#chainSourceName').textContent=$('#sourceOwnerInput').value.trim()||'—';
  $('#chainApplicantName').textContent=$('#applicantInput').value.trim()||'—';
}

function renderOwnershipCase(force=false){
  const sample=ownershipSamples[currentCase];
  if(!sample)return;
  const changed=ownershipLoadedCase!==currentCase;
  const sourceLabel=cases[currentCase].type==='inheritance'?tr('chainInheritanceLabel'):tr('chainSaleLabel');
  $('#chainSourceLabel').textContent=sourceLabel;
  $('#sourceOwnerField').textContent=cases[currentCase].type==='inheritance'?tr('sourceInheritanceField'):tr('sourceSaleField');
  if(force||changed||!ownershipEdited){
    $('#recordOwnerInput').value=local(sample.recordOwner);$('#sourceOwnerInput').value=local(sample.source);$('#applicantInput').value=local(sample.applicant);$('#applicantDocNameInput').value=local(sample.applicantDocName);
    $('#recordMouzaInput').value=local(sample.recordMouza);$('#documentMouzaInput').value=local(sample.documentMouza);$('#recordPlotInput').value=sample.recordPlot;$('#documentPlotInput').value=sample.documentPlot;$('#recordAreaInput').value=sample.recordArea;$('#sourceAreaInput').value=sample.sourceArea;$('#claimedAreaInput').value=sample.claimedArea;
    $('#sourceLinkCheck').checked=sample.sourceLinked;$('#applicantLinkCheck').checked=sample.applicantLinked;
    if(force||changed){ownershipLoadedCase=currentCase;ownershipHasRun=false;ownershipEdited=false;}
  }
  updateOwnershipPath();
  if(ownershipHasRun)runOwnershipCheck();else showOwnershipInitial();
}

function showOwnershipInitial(){
  const result=$('#ownershipResult');result.className='ownership-result';
  result.innerHTML=`<span class="result-mark">i</span><div><strong>${tr('ownershipInitialTitle')}</strong><p>${tr('ownershipInitialText')}</p></div>`;
}

function normalizeBanglaDigits(value){
  const bnDigits='০১২৩৪৫৬৭৮৯';
  return String(value).replace(/[০-৯]/g,d=>String(bnDigits.indexOf(d)));
}

function normalizeLandText(value){
  return String(value).normalize('NFC').toLocaleLowerCase().replace(/[\u200c\u200d]/g,'').replace(/[^\p{L}\p{N}]/gu,'');
}

function parseArea(value){
  const normalized=normalizeBanglaDigits(value).trim();
  if(!/^(?:\d+(?:\.\d*)?|\.\d+)$/.test(normalized))return NaN;
  return Number(normalized);
}

function evaluateOwnership(values){
  const issues=[];
  const recordName=normalizeLandText(values.recordOwner),sourceName=normalizeLandText(values.sourceOwner);
  const applicantName=normalizeLandText(values.applicant),paperApplicantName=normalizeLandText(values.applicantDocName);
  const namesDiffer=!!recordName&&!!sourceName&&recordName!==sourceName;
  const applicantNameDiff=!!applicantName&&!!paperApplicantName&&applicantName!==paperApplicantName;
  if(!values.recordOwner.trim()||!values.sourceOwner.trim()||!values.applicant.trim()||!values.applicantDocName.trim())issues.push('ownershipMissingName');
  if(applicantNameDiff)issues.push('ownershipApplicantNameMismatch');
  const recordMouza=normalizeLandText(values.recordMouza),documentMouza=normalizeLandText(values.documentMouza);
  if(!recordMouza||!documentMouza)issues.push('ownershipMouzaMissing');else if(recordMouza!==documentMouza)issues.push('ownershipMouzaMismatch');
  const recordPlot=normalizeBanglaDigits(values.recordPlot).trim().replace(/\s+/g,'').toLocaleLowerCase();
  const documentPlot=normalizeBanglaDigits(values.documentPlot).trim().replace(/\s+/g,'').toLocaleLowerCase();
  if(!recordPlot||!documentPlot)issues.push('ownershipMissingPlot');else if(recordPlot!==documentPlot)issues.push('ownershipPlotMismatch');
  const recordArea=parseArea(values.recordArea),sourceArea=parseArea(values.sourceArea),claimedArea=parseArea(values.claimedArea);
  if(!Number.isFinite(recordArea)||!Number.isFinite(sourceArea)||!Number.isFinite(claimedArea)||recordArea<=0||sourceArea<=0||claimedArea<=0)issues.push('ownershipAreaInvalid');
  else{if(sourceArea>recordArea+0.0000001)issues.push('ownershipSourceAreaExceeds');if(claimedArea>sourceArea+0.0000001)issues.push('ownershipClaimedAreaExceeds');}
  if(!values.sourceLinkChecked)issues.push(namesDiffer?'ownershipNameDiff':'ownershipSourceUnconfirmed');
  if(!values.applicantLinkChecked)issues.push('ownershipApplicantUnconfirmed');
  return {issues,namesDiffer,applicantNameDiff};
}

function runOwnershipCheck(){
  ownershipHasRun=true;updateOwnershipPath();
  const resultData=evaluateOwnership({
    recordOwner:$('#recordOwnerInput').value,sourceOwner:$('#sourceOwnerInput').value,applicant:$('#applicantInput').value,applicantDocName:$('#applicantDocNameInput').value,
    recordMouza:$('#recordMouzaInput').value,documentMouza:$('#documentMouzaInput').value,recordPlot:$('#recordPlotInput').value,documentPlot:$('#documentPlotInput').value,
    recordArea:$('#recordAreaInput').value,sourceArea:$('#sourceAreaInput').value,claimedArea:$('#claimedAreaInput').value,sourceLinkChecked:$('#sourceLinkCheck').checked,applicantLinkChecked:$('#applicantLinkCheck').checked
  });
  const {issues,namesDiffer,applicantNameDiff}=resultData;const result=$('#ownershipResult');
  if(issues.length){
    result.className='ownership-result attention';
    result.innerHTML=`<span class="result-mark">!</span><div><strong>${tr('ownershipNeedsTitle')}</strong><ul>${issues.map(key=>`<li>${tr(key)}</li>`).join('')}</ul>${namesDiffer&&$('#sourceLinkCheck').checked?`<p class="ownership-name-note">${tr('ownershipNameDiffChecked')}</p>`:''}${applicantNameDiff?`<p class="ownership-name-note">${tr('ownershipApplicantNameDiffNote')}</p>`:''}<p class="ownership-limit">${tr('ownershipCheckLimit')}</p></div>`;
  }else{
    result.className='ownership-result success';
    result.innerHTML=`<span class="result-mark">✓</span><div><strong>${tr('ownershipPassTitle')}</strong><p>${tr('ownershipPassText')}</p><p class="ownership-limit">${tr('ownershipCheckLimit')}</p></div>`;
  }
}

